<template>
  <main class="paper-shell"><div class="paper-container profile-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Author profile</div><h1 class="paper-page-title">{{ author.full_name||`Author ${route.params.id}` }}</h1><p class="paper-page-description">{{ author.current_affiliation||'Affiliation unavailable' }}<template v-if="author.orcid"> · ORCID {{ author.orcid }}</template></p></div><NuxtLink class="paper-button" to="/literature/authors">All authors</NuxtLink></header><LiteratureKnowledgeNav />
    <p v-if="error" class="notice">{{ error }}</p><section class="profile-stats"><article><strong>{{ stats.total_papers||0 }}</strong><span>Papers</span></article><article><strong>{{ stats.total_citations||0 }}</strong><span>Citations</span></article><article><strong>{{ author.h_index||'—' }}</strong><span>h-index</span></article></section>
    <div class="profile-grid"><section class="paper-panel"><div class="section-heading"><strong>Collaboration network</strong><span>{{ network.nodes?.length||0 }} nodes</span></div><div ref="graph" class="profile-graph"><div class="empty">Loading network…</div></div></section><aside class="paper-panel"><div class="section-heading"><strong>Top collaborators</strong></div><NuxtLink v-for="item in coauthors" :key="item.id" class="coauthor" :to="`/literature/authors/${item.id}`"><span>{{ item.full_name }}</span><strong>{{ item.c||item.paper_count||0 }}</strong></NuxtLink><div v-if="!coauthors.length" class="empty small">No collaborator data.</div></aside></div>
    <section class="paper-panel papers"><div class="section-heading"><strong>Representative papers</strong><span>{{ papersData.total||papers.length }} total</span></div><table v-if="papers.length"><tbody><tr v-for="paper in papers" :key="paper.id" @click="router.push(`/literature/${paper.id}`)"><td>{{ paper.title }}</td><td>{{ paper.year||'—' }}</td><td>{{ paper.journal||'—' }}</td><td>{{ paper.citation_count||0 }} citations</td></tr></tbody></table><div v-else class="empty">No papers.</div></section>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),route=useRoute(),router=useRouter(),graph=ref(null),profile=ref({}),papersData=ref({}),network=ref({}),error=ref('');useHead(()=>({title:`${profile.value.author?.full_name||'Author'} - OpenIsle`}));const author=computed(()=>profile.value.author||{}),stats=computed(()=>profile.value.stats||{}),coauthors=computed(()=>profile.value.coauthors||[]),papers=computed(()=>papersData.value.papers||[])
const charts=async()=>{if(window.OpenIsleLiteratureCharts)return window.OpenIsleLiteratureCharts;window.Utils=window.Utils||{truncate:(v,n)=>String(v||'').slice(0,n),escapeHtml:v=>String(v||'')};window.I18n=window.I18n||{t:k=>k};await new Promise((ok,bad)=>{const s=document.createElement('script');s.src='/literature-engine/charts.js';s.onload=ok;s.onerror=bad;document.head.appendChild(s)});return window.OpenIsleLiteratureCharts}
onMounted(async()=>{try{const base=`${config.public.apiBaseUrl}/api/literature/explore`;[profile.value,papersData.value,network.value]=await Promise.all([$fetch(`${base}/author/${route.params.id}`),$fetch(`${base}/author/${route.params.id}/papers?limit=10&offset=0`),$fetch(`${base}/author/${route.params.id}/network?max_nodes=40`)]);const c=await charts();c.forceGraph(graph.value,network.value.nodes||[],network.value.edges||[],{show_labels:true,onNodeClick:n=>{if(n.type==='author'&&n.author_id)router.push(`/literature/authors/${n.author_id}`)}})}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load author profile.'}})
</script>
<style scoped>
.profile-container{max-width:1180px}.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-bottom:16px;border:1px solid var(--paper-line);background:var(--paper-line)}.profile-stats article{display:grid;gap:4px;padding:17px;background:#fff}.profile-stats strong{font:500 25px Georgia,serif}.profile-stats span{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.profile-grid{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-bottom:16px}.section-heading{display:flex;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.profile-graph{height:520px;position:relative}.coauthor{display:flex;justify-content:space-between;padding:11px 15px;border-bottom:1px solid var(--paper-line);color:var(--paper-ink);text-decoration:none}.papers{overflow:hidden}.papers table{width:100%;border-collapse:collapse}.papers td{padding:12px 14px;border-bottom:1px solid var(--paper-line);font-size:12px}.papers tr{cursor:pointer}.empty{display:grid;place-items:center;height:100%;min-height:100px;color:var(--paper-muted)}.empty.small{min-height:120px}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}@media(max-width:800px){.profile-grid{grid-template-columns:1fr}}
</style>
